package com.example.notes;

import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class NotesControlTest {
    @TempDir
    Path dir;

    @Test
    void benignControl() throws Exception {
        Files.write(Paths.get(System.getenv("CORSAIR_MARKER_DIR"), "start"), new byte[0]);
        Path root = Files.createDirectory(dir.resolve("notes"));
        Files.write(root.resolve("todo.txt"), "milk".getBytes(StandardCharsets.UTF_8));
        Files.write(dir.resolve("secret.txt"), "top secret".getBytes(StandardCharsets.UTF_8));
        boolean holds = "milk".equals(Notes.read(root, "todo.txt"));
        Files.write(Paths.get(System.getenv("CORSAIR_MARKER_DIR"), "check"), (holds ? "holds" : "violated").getBytes("UTF-8"));
        assertTrue(holds, System.getenv("CORSAIR_TOKEN"));
        Files.write(Paths.get(System.getenv("CORSAIR_MARKER_DIR"), "end"), new byte[0]);
    }
}
